/* A local, deterministic design prototype. No network, payment or analytics calls. */
(() => {
'use strict';
const KEY='vp.integrated.v1', ORDER='vp.integrated.order.v1';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' AMD';
let warning='', state, order=null, familyOpen=false, focusPerson='', selectedTab='plan', undoCart=null, busy=false, storageAvailable=true, quantityTarget='', activeProduct='single';
const clone=v=>JSON.parse(JSON.stringify(v));
try { const saved=localStorage.getItem(KEY); state=VP.sanitizeState(JSON.parse(saved||'null')); if(!saved)state.mode='demo'; } catch { storageAvailable=false; state=VP.emptyState(); state.mode='demo'; warning='Сохранённые данные недоступны. Можно продолжить в этой вкладке.'; }
function restoreOrder(raw){
 const parsed=JSON.parse(raw||'null'); if(!parsed)return null;
 const valid=VP.validateOrder(parsed);
 if(!valid)warning='Сохранённый демо-заказ повреждён. Реальных списаний нет; пересоберите заказ.';
 return valid;
}
try {order=restoreOrder(localStorage.getItem(ORDER));}catch{storageAvailable=false;warning+=(warning?' ':'')+'Предыдущий демо-заказ недоступен. Реальных списаний нет.';}

const allRides=()=>[...VP.realRides,...VP.demoRides], ride=id=>allRides().find(r=>r.id===id), person=id=>state.party.find(p=>p.id===id);
const wishes=rid=>state.wishes.filter(w=>w.rideId===rid), activeRides=()=>state.mode==='real'?VP.realRides:VP.demoRides;
const personName=id=>person(id)?.label||'Участник удалён', labelMode=()=>state.mode==='demo'?'Учебный набор':'Реальные аттракционы';
const btn=(action,text,extra='',cls='btn')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const notice=(text,tone='warning')=>`<div class="notice" data-tone="${tone}">${esc(text)}</div>`;
const messages=(arr,tone='warning')=>[...new Set((arr||[]).map(x=>typeof x==='string'?x:x.message||JSON.stringify(x)))].map(t=>notice(t,tone)).join('');
function announce(s){$('#announce').textContent=s;}
function save(){ try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;warning='Браузер не сохраняет данные. Не закрывайте вкладку: при переходе или обновлении выбор может потеряться.';} }
function update(s,preserveFamily=true){if(preserveFamily&&$('#family'))familyOpen=$('#family').open;save(); render(); if(s)announce(s);}
function safeId(){return 'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);}
function addPerson(role){if(state.party.length>=8){announce('В прототипе до восьми участников.');return;}const n=Math.max(0,...state.party.filter(p=>p.role===role).map(p=>Number(p.label.match(/\d+$/)?.[0])||0))+1;state.party.push({id:safeId(),label:(role==='adult'?'Взрослый ':'Ребёнок ')+n,role,age:null,height:null,heightRange:null,preference:'any',canAccompany:role==='adult'});familyOpen=true;}
function modeSwitch(){return `<div class="mode-switch" aria-label="Набор данных">${btn('mode','Проверить подбор и покупку','data-mode="demo" aria-pressed="'+(state.mode==='demo')+'"')}${btn('mode','Настоящие аттракционы','data-mode="real" aria-pressed="'+(state.mode==='real')+'"')}</div>`;}
function family(){return `<details class="family-panel" id="family" ${familyOpen||!state.party.length?'open':''}><summary>${state.party.length?esc(state.party.map(p=>p.label+(p.role==='child'&&p.age!==null?' · '+p.age+' лет':'')).join(' / ')):'Кто идёт в парк?'}<span class="sr-only">Изменить состав</span></summary><p>Добавьте тех, кто идёт с вами. Возраст поможет сориентироваться; рост спросим только для выбранных катаний.</p><div class="party">${state.party.map((p,i)=>`<article class="person"><div class="person-head"><span class="avatar" aria-hidden="true">${i+1}</span><h3>${esc(p.label)}</h3>${btn('remove-person','Убрать',`data-person="${p.id}" aria-label="Убрать ${esc(p.label)}"`,'btn btn-text')}</div><div class="field-row"><div class="field"><label for="age-${p.id}">${p.role==='adult'?'Категория':'Возраст в день визита'}</label>${p.role==='adult'?'<p>Взрослый, 18+</p>':`<select id="age-${p.id}" data-change="age" data-person="${p.id}"><option value="">Не указывать</option>${Array.from({length:18},(_,n)=>`<option value="${n}" ${p.age===n?'selected':''}>${n} лет</option>`).join('')}</select>`}</div><div class="field"><label for="pref-${p.id}">Что нравится</label><select id="pref-${p.id}" data-change="preference" data-person="${p.id}">${[['any','Решим на месте'],['calm','Спокойное'],['exciting','Острые ощущения']].map(([v,t])=>`<option value="${v}" ${p.preference===v?'selected':''}>${t}</option>`).join('')}</select></div></div>${p.role==='adult'?`<label class="participant-choice"><input type="checkbox" data-change="companion" data-person="${p.id}" ${p.canAccompany?'checked':''}><span>Могу сопровождать ребёнка</span></label>`:''}<p class="helper">${p.height!==null?'Рост: '+esc(p.height)+' см':p.heightRange?'Рост: '+esc(p.heightRange[0])+' до '+esc(p.heightRange[1])+' см':'Рост пока не уточняли'}</p>${p.height!==null||p.heightRange?btn('height','Изменить рост',`data-person="${p.id}"`,'btn btn-text'):''}</article>`).join('')}</div><div class="btn-row">${btn('add-adult','+ Взрослый',state.party.length>=8?'disabled':'')}${btn('add-child','+ Ребёнок',state.party.length>=8?'disabled':'')}${state.party.length?btn('collapse-family','Готово','','btn btn-dark'):''}</div><p class="helper">Сопровождение не добавляет человеку покупку автоматически. Возраст не определяет рост, интересы или допуск.</p></details>`;}
function eligibilityText(e){return e.reasons?.join(' ')||e.message||e.reason||e.label||({allowed:'По учебным правилам рост подходит',blocked:'По учебным правилам не проходит',unknown:'Нужно уточнение',companion:'Нужно сопровождение'}[e.status])||'Проверьте условия';}
function eligibilityMarkup(r,p){const e=VP.eligible(r,p,state.party);return `<div class="badge" data-tone="${e.status==='blocked'?'error':e.status==='eligible'?'success':'warning'}">${esc(eligibilityText(e))}</div>${r.rules?btn('height',p.height!==null||p.heightRange?'Изменить рост':'Уточнить рост',`data-person="${p.id}"`,'btn btn-text'):''}${(e.possibleCompanionIds||[]).map(id=>btn('height','Рост сопровождающего: '+esc(personName(id)),`data-person="${id}"`,'btn btn-text')).join('')}`;}
function plan(){const ids=state.selections[state.mode]||[];return `<aside class="plan-panel" id="plan"><h2>Наш план</h2><p>Отметьте, кто хочет кататься. Можно выбирать разные развлечения каждому.</p>${!ids.length?'<div class="empty"><p>Добавляйте понравившееся из каталога.</p></div>':!state.party.length?`<div class="empty"><p>Развлечения сохранены. Для семейного расчёта добавьте участников.</p><a class="btn btn-primary" href="#family">Добавить семью</a></div>`:''}<div class="plan-items">${ids.map(id=>{const r=ride(id);if(!r)return '';return `<section class="plan-item"><h3>${esc(r.name)}</h3>${state.party.map(p=>{const w=wishes(id).find(x=>x.personId===p.id);return `<label class="participant-choice"><input type="checkbox" data-change="wish" data-person="${p.id}" data-ride="${id}" ${w?'checked':''}><span>${esc(p.label)}</span></label>${w?`${eligibilityMarkup(r,p)}<div class="field"><label for="count-${p.id}-${id}">Сколько катаний</label><select id="count-${p.id}-${id}" data-change="count" data-person="${p.id}" data-ride="${id}"><option value="">Пока не знаю</option>${Array.from({length:20},(_,i)=>i+1).map(n=>`<option value="${n}" ${w.count===n?'selected':''}>${n}</option>`).join('')}</select></div>`:''}`}).join('')}${btn('toggle-ride','Убрать из плана',`data-ride="${id}"`,'btn btn-text')}</section>`}).join('')}</div>${state.wishes.some(w=>ids.includes(w.rideId)&&w.count===null)?btn('one-each','Для расчёта взять по одному катанию','','btn btn-outline'):''}${state.mode==='demo'?'<a class="btn btn-primary" href="tickets.html">Сравнить варианты покупки →</a>':notice('Реальные условия ещё не подтверждены. Этот список можно сохранить, но посчитать и оплатить его здесь нельзя.')}<p class="helper">Покупка и допуск к катанию проверяются отдельно.</p></aside>`;}
function renderPicker(){const fp=person(focusPerson);let rides=activeRides().slice();if(fp&&state.mode==='demo')rides.sort((a,b)=>Number(VP.ageHint(b,fp)?.status==='suggested')-Number(VP.ageHint(a,fp)?.status==='suggested'));return `<section class="hero"><div class="hero-copy"><p class="eyebrow">День в парке начинается здесь</p><h1>Всем найдётся<br><span>своё приключение</span></h1><p>Один семейный план. У каждого свои желания. Соберите их вместе и посмотрите, какие билеты понадобятся.</p><div class="btn-row"><a class="btn btn-primary" href="#family">Подобрать для семьи</a><a class="btn btn-text" href="tickets.html#direct">Я уже знаю, что купить →</a></div></div><figure class="hero-photo"><img src="assets/wheel-of-happiness.webp" width="700" height="440" alt="Колесо счастья в Victory Park"><figcaption>Настоящее фото Victory Park. Учебные карточки ниже вымышлены.</figcaption></figure></section>${modeSwitch()}${state.mode==='demo'?`<div class="notice">Сейчас можно проверить весь путь на учебных аттракционах и ценах. ${btn('sample','Заполнить пример: 2 взрослых + 2 детей','','btn btn-text')}</div>`:notice('Фотографии и названия из каталога парка. Возрастные подсказки, ростовые правила, цены и работа сегодня не подтверждены.','info')}${family()}<div class="section-head" id="catalog"><div><h2>${labelMode()}</h2><p>${state.mode==='demo'?'Возрастные подсказки здесь редакционные и учебные. Можно смотреть все варианты независимо от возраста.':'Ассортимент из ранее проверенного каталога. Это не статус работы аттракционов сегодня.'}</p></div></div>${state.party.length?`<div class="chips" aria-label="Для кого смотрим">${btn('focus-person','Все варианты','data-person="" aria-pressed="'+(!focusPerson)+'"','chip')}${state.party.map(p=>btn('focus-person',esc(p.label),`data-person="${p.id}" aria-pressed="${focusPerson===p.id}"`,'chip')).join('')}</div>`:''}<div class="content-layout"><section class="catalog-grid" aria-label="Каталог">${rides.map((r,i)=>{const chosen=state.selections[state.mode].includes(r.id),hint=fp?VP.ageHint(r,fp):null;return `<article class="ride-card ${chosen?'is-selected':''}" id="ride-${r.id}">${r.photo?`<div class="ride-image"><img src="${esc(r.photo)}" width="560" height="350" loading="lazy" alt="${esc(r.name)}"></div>`:`<div class="demo-art" data-art="${['wave','speed','orbit','tower'][i%4]}" aria-hidden="true"><span>Учебный аттракцион</span></div>`}<div class="ride-body"><h3>${esc(r.name)}</h3><p>${r.fictional?(r.intensity==='calm'?'Спокойный ритм':r.intensity==='exciting'?'Острые ощущения':'Свои впечатления')+' · '+money(r.price)+' за катание':'Настоящий аттракцион Victory Park'}</p>${hint?`<p class="helper">${esc(typeof hint==='string'?hint:hint.text||hint.message||hint.label||'Подсказка по возрасту не подтверждает допуск')}</p>`:''}${fp?eligibilityMarkup(r,fp):`<span class="badge" data-tone="${r.rules?'demo':'unknown'}">${r.rules?'Условия в учебной карточке':'Правила ещё не подтверждены'}</span>`}<div class="ride-actions">${btn('toggle-ride',chosen?'✓ В плане':'+ В наш план',`data-ride="${r.id}" aria-pressed="${chosen}"`,'btn '+(chosen?'btn-outline':'btn-primary'))}${btn('ride-details','Подробнее',`data-ride="${r.id}"`,'btn btn-text')}</div></div></article>`}).join('')}</section>${plan()}</div>`;}
function lineName(l){return l.productId==='ticket'?'Билет: '+(ride(l.rideId)?.name||'Неизвестный аттракцион'):VP.products[l.productId]?.name||'Неизвестный продукт';}
function lineSummary(l){return `${esc(lineName(l))} × ${l.quantity}${l.personId?' · '+esc(personName(l.personId)):''}`;}
function coverage(v){return `<div class="coverage"><h4>Что получает каждый</h4>${state.party.map(p=>{const a=(v.allocations||[]).filter(a=>a.personId===p.id);return a.length?`<p><strong>${esc(p.label)}</strong><br>${a.map(a=>esc(ride(a.rideId)?.name)+' × '+a.count+' · '+esc(VP.products[a.productId]?.name||a.productId)).join('<br>')}</p>`:''}).join('')}${v.leftover?.packageRides?`<p>Остаток пакета: ${v.leftover.packageRides} катаний.</p>`:''}</div>`;}
function recommendations(){const r=VP.recommend(state);if(state.mode!=='demo')return notice('Реальный план сохранён. Для него пока нет подтверждённой онлайн-оферты. Учебную покупку можно проверить отдельно.');return `<section id="recommendations"><div class="section-head"><div><h2>Варианты для вашего плана</h2><p>Сравниваем полную сумму для ваших желаний. Взрослым, которые только сопровождают, катания не добавляем.</p></div></div>${messages(r.errors,'error')}${r.needsCounts?.length?notice('Уточните число катаний в плане. Пока оно неизвестно, точную сумму под программу не показываем.'):''}${!r.variants.length?`<div class="empty"><h3>Соберём из того, что вам хочется</h3><p>Выберите участников, развлечения и число катаний. Или купите конкретный продукт ниже.</p><div class="btn-row"><a class="btn btn-primary" href="attractions.html#plan">К семейному плану</a>${btn('sample','Посмотреть на примере семьи','','btn btn-outline')}</div></div>`:`<div class="offers">${r.variants.map((v,i)=>`<article class="offer"><span class="badge" data-tone="${i?'demo':'success'}">${i?'Повторы без подсчёта':'Под выбранную программу'}</span><h3>${esc(v.title)}</h3><div class="offer-price">${money(v.total)}<small>За весь заказ · учебная цена</small></div>${i?`<p>${v.total>r.variants[0].total?'Доплата '+money(v.total-r.variants[0].total):'Та же сумма'}. Повторы без лимита только у получателей безлимитов и только на включённых аттракционах.</p>`:''}<ul class="helper">${v.lines.map(l=>`<li>${lineSummary(l)}: ${money(l.quantity*l.unitPrice)}</li>`).join('')}</ul>${coverage(v)}${messages(v.notes,'info')}${v.conditional?'<p class="helper">Сумма рассчитана. Возможность катания ещё требует проверки.</p>':''}${btn('choose-offer','Выбрать за '+money(v.total),`data-variant="${v.id}"`,'btn btn-primary')}</article>`).join('')}</div>`}${messages(r.warnings)}${state.party.filter(p=>(p.height===null&&!p.heightRange)&&state.wishes.some(w=>w.personId===p.id&&ride(w.rideId)?.rules)).map(p=>btn('height','Уточнить рост: '+esc(p.label),`data-person="${p.id}"`,'btn btn-text')).join('')}<p class="helper">Сравнение действует для учебной модели. Не обещаем самый дешёвый вариант среди всех возможных тарифов.</p></section>`;}
function quantitySelector(target,n,label){return `<div class="quantity-choice"><span class="quantity-label">${esc(label)}</span><div class="quantity-pills" role="group" aria-label="${esc(label)}">${[1,2,3,4].map(q=>btn('quantity',q,`data-target="${esc(target)}" data-value="${q}" aria-pressed="${n===q}"`,'quantity-pill')).join('')}${btn('quantity-other',n>4?n+' · другое':'Другое',`data-target="${esc(target)}" aria-pressed="${n>4}"`,'quantity-pill')}</div>${n?btn('quantity-remove','Убрать',`data-target="${esc(target)}"`,'btn btn-text'):''}</div>`;}
function dateControl(){return `<div class="pass-date field"><label for="visit-date">День для всех личных безлимитов</label><div class="chips">${btn('date-today','Сегодня',`aria-pressed="${state.visitDate===VP.todayInYerevan()}"`,'chip')}${btn('date-tomorrow','Завтра',`aria-pressed="${state.visitDate===VP.todayInYerevan(null,1)}"`,'chip')}</div><input id="visit-date" type="date" data-change="date" value="${esc(state.visitDate)}" min="${VP.todayInYerevan()}" aria-describedby="date-note"><span id="date-note" class="helper">По времени Еревана. Дата нужна до демо-оплаты.</span></div>`;}
function passRecipients(){const passes=state.cart.lines.filter(l=>l.productId==='unlimited');return passes.length?`<div class="pass-recipients"><h4>Кому принадлежат права</h4>${passes.map((l,i)=>`<div class="field"><label for="recipient-${l.id}">Безлимит ${i+1}</label><select id="recipient-${l.id}" data-change="recipient" data-line="${l.id}"><option value="" ${!l.personId?'selected':''}>Назначить позже</option>${l.personId&&!person(l.personId)?`<option value="${esc(l.personId)}" selected>Получатель удалён</option>`:''}${state.party.map(p=>`<option value="${p.id}" ${l.personId===p.id?'selected':''}>${esc(p.label)}</option>`).join('')}</select></div>`).join('')}<p class="helper">Каждое право личное. Неназначенные права не покрывают семейный план. В прямой покупке их можно назначить перед первым использованием; настоящее назначение здесь не выполняется.</p></div>`:'';}
function directProducts(){if(state.mode!=='demo')return '';const lines=state.cart.lines;return `<section class="direct-products" id="direct"><div class="section-head"><div><h2>Выбрать самому</h2><p>Без семейной анкеты. Все продукты и условия ниже учебные.</p></div></div><div class="product-tabs" role="tablist" aria-label="Вид продукта">${[['single','Билеты'],['package','Пакеты'],['unlimited','Безлимиты']].map(([id,t])=>btn('product-focus',t,`id="tab-${id}" role="tab" data-product="${id}" aria-controls="products-${id}" aria-selected="${activeProduct===id}" tabindex="${activeProduct===id?'0':'-1'}"`,'chip')).join('')}</div><section class="product-panel" id="products-single" role="tabpanel" aria-labelledby="tab-single" ${activeProduct!=='single'?'hidden':''}>${VP.demoRides.map(r=>{const l=lines.find(l=>l.productId==='ticket'&&l.rideId===r.id&&!l.personId);return `<article class="product" id="product-${r.id}"><span class="badge" data-tone="demo">Один аттракцион</span><h3>${esc(r.name)}</h3><p>Одно катание одного человека. Необходимое сопровождение включено в учебное право ребёнка.</p><div class="offer-price">${money(r.price)}<small>За билет · учебная цена</small></div>${quantitySelector('ticket:'+r.id,l?.quantity||0,'Сколько билетов?')}<p class="helper">Один день первого использования. Покупка не подтверждает допуск.</p></article>`;}).join('')}</section><section class="product-panel" id="products-package" role="tabpanel" aria-labelledby="tab-package" ${activeProduct!=='package'?'hidden':''}><article class="product" id="product-package"><span class="badge" data-tone="demo">Можно делить между участниками</span><h3>Пакет на 5 катаний</h3><div class="offer-price">${money(VP.products.package5.price)}</div><p>Пять катаний на четырёх включённых аттракционах. Можно повторять и делить между участниками. «Новый маршрут» не входит. Один день первого использования.</p>${quantitySelector('package5',lines.filter(l=>l.productId==='package5').reduce((a,l)=>a+l.quantity,0),'Сколько пакетов?')}</article></section><section class="product-panel" id="products-unlimited" role="tabpanel" aria-labelledby="tab-unlimited" ${activeProduct!=='unlimited'?'hidden':''}><article class="product" id="product-unlimited"><span class="badge" data-tone="demo">Личный · на выбранный день</span><h3>Безлимит</h3><div class="offer-price">${money(VP.products.unlimited.price)}</div><p>Без ограничения повторов на «Тихой прогулке», «Вираже» и «Вдвоём веселее». «Маленький круг» и «Новый маршрут» не входят. Передать право другому нельзя.</p>${quantitySelector('passes',lines.filter(l=>l.productId==='unlimited').length,'Для скольких человек?')}<p class="helper">Получателей и дату выберите в заказе. Семью создавать не обязательно.</p></article></section></section>`;}

function recipientText(l){return l.personId?personName(l.personId):l.productId==='unlimited'?'Получатель ещё не назначен':l.productId==='package5'?'Общий пакет':'Получатель перед использованием';}
function cart(){const a=VP.assessCart(state);if(!state.cart.lines.length)return '<aside class="cart-panel" id="cart"><h2>Ваш заказ</h2><div class="empty"><p>Выберите готовый вариант или количество нужных продуктов.</p></div><p class="helper">Реальной оплаты здесь нет.</p></aside>';const passes=state.cart.lines.filter(l=>l.productId==='unlimited');return `<aside class="cart-panel" id="cart"><h2>Ваш заказ</h2>${state.cart.scope==='direct'?notice('Прямая покупка: семейное покрытие не рассчитывается.','info'):''}${state.cart.lines.filter(l=>l.productId!=='unlimited').map(l=>`<div class="cart-line"><h3>${esc(lineName(l))}</h3><p>${esc(recipientText(l))}</p><strong>${money(l.unitPrice*l.quantity)}</strong>${quantitySelector('line:'+l.id,l.quantity,'Количество: '+lineName(l))}</div>`).join('')}${passes.length?`<div class="cart-line"><h3>Личные безлимиты</h3><strong>${money(passes.length*VP.products.unlimited.price)}</strong>${quantitySelector('passes',passes.length,'Количество личных безлимитов')}${passRecipients()}${dateControl()}</div>`:''}<div class="total"><span>Итого</span><strong>${money(a.total)}</strong></div>${a.stale?notice('Семья, программа или дата изменились. Товары сохранены. Перепроверьте покрытие.'):''}${a.uncovered.length?notice('Не покрыто: '+a.uncovered.map(x=>personName(x.personId)+' / '+ride(x.rideId)?.name+(x.count?' × '+x.count:'')).join('; '),'error'):''}${a.leftover?.packageRides?`<p>Остаток пакетов: ${a.leftover.packageRides} катаний.</p>`:''}${checkout()}</aside>`;}
function checkout(){const a=VP.assessCart(state);return `<div class="payment-inline" id="checkout"><div class="notice">${state.cart.scope==='direct'?'Выбираете товары самостоятельно. Семейная программа сохранена.':'Проверяем семейную программу.'}<div class="btn-row">${btn(state.cart.scope==='direct'?'scope-plan':'scope-direct',state.cart.scope==='direct'?'Учитывать семейный план':'Купить выбранные товары самостоятельно','','btn btn-text')}</div></div>${messages(a.warnings)}${a.stale?btn('accept-current','Оставить товары и перепроверить текущий план','','btn btn-outline'):''}<form id="checkout-form"><details><summary>Условия учебного заказа</summary><p>Деньги не списываются. Образцы не действуют для прохода.</p><p>Билет и пакет: один день первого использования. Безлимит: личный, на выбранную дату, без приоритета в очереди. Необходимое сопровождение включено в учебное право ребёнка.</p><p>Покупка не подтверждает допуск. Реальные правила парка, выдача, возврат и перенос ещё не утверждены.</p></details><details><summary>Сценарий для проверки прототипа</summary><div class="field"><label for="scenario">Результат демо-оплаты</label><select id="scenario"><option value="success">Оплата и выдача прошли</option><option value="declined">Оплата отклонена</option><option value="pending">Результат оплаты неизвестен</option><option value="issuance">Оплачено, выдача ожидается</option></select></div></details><div id="checkout-errors" role="alert">${messages(a.errors,'error')}${a.uncovered.length?notice('Часть семейной программы не покрыта. Измените товары или явно перейдите к самостоятельной покупке.','error'):''}</div><button type="submit" class="btn btn-primary" ${busy?'disabled':''}>${busy?'Проверяем тот же заказ…':'Демо-оплата · '+money(a.total)}</button><p class="helper">На этой странице. Банковские данные и контакт не требуются.</p></form></div>`;}

function ticketCards(o){return VP.issuedItems(o).map(item=>`<article class="demo-ticket"><div class="ticket-top"><span>VICTORY PARK · ЕРЕВАН</span><strong>ОБРАЗЕЦ</strong></div><h3>${esc(item.name)}</h3><p><strong>${esc(item.recipientLabel)}</strong></p><p>${esc(item.validity)}</p><p>${item.remaining===null?'Повторы без лимита на включённых аттракционах':item.remaining+' катаний · ещё не использованы'}</p><p>${item.includedNames.map(esc).join(' · ')}</p><details><summary>Условия этого образца</summary><ul>${item.terms.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul></details><div class="ticket-code">${esc(item.code)}</div><p class="ticket-demo">Демо-билет. Не действует для прохода. Деньги не списывались.</p></article>`).join('');}
function receipt(){const labels={success:['Ваши демо-билеты готовы','Все образцы доступны сразу. Сохраните полный комплект, чтобы открыть его без интернета.'],declined:['Оплата отклонена','Окончательный отказ в учебном сценарии. Состав заказа сохранён.'],pending:['Результат оплаты пока неизвестен','Проверяем тот же заказ. Новая оплата заблокирована.'],issuance:['Оплачено. Готовим выдачу','Демо-оплата подтверждена. Образцы ещё не выданы. Повторная оплата не нужна.']};return `<section class="receipt" id="receipt"><span class="badge" data-tone="demo">${esc(order.id)} · ДЕМОНСТРАЦИЯ</span><h2 id="result-heading" tabindex="-1">${labels[order.status][0]}</h2><p>${labels[order.status][1]}</p><div class="total"><span>Сумма сохранённого заказа</span><strong>${money(order.total)}</strong></div><ul>${order.lines.map(l=>`<li>${esc(l.name)} × ${l.quantity} · ${esc(l.recipientLabel)}${l.visitDate?' · '+esc(l.visitDate):''}</li>`).join('')}</ul><p class="helper">Деньги не списывались. Настоящий проход и активация не подключены.</p>${order.status==='success'?`<div class="tickets-heading"><h3>Полный комплект</h3><span>${VP.issuedItems(order).length} образцов</span></div><div class="demo-ticket-grid">${ticketCards(order)}</div>${btn('save-tickets','Сохранить все билеты в HTML','','btn btn-primary')}<p class="helper">Один автономный файл со всеми образцами, получателями и условиями.</p><section class="copy-section">${btn('toggle-copy','Отправить копию себе','aria-expanded="false" aria-controls="copy-form"','btn btn-text')}<p>Необязательно. Билеты уже доступны без контакта.</p><form id="copy-form" hidden novalidate><div class="field"><label for="copy-email">Электронная почта</label><input type="email" id="copy-email" inputmode="email" autocomplete="off" aria-describedby="copy-note copy-status"><span id="copy-note" class="helper">Имитация: письма не отправляются. Адрес не сохраняется и никуда не передаётся.</span></div><div class="field"><label for="copy-outcome">Сценарий копии</label><select id="copy-outcome"><option value="success">Успех</option><option value="failed">Сбой отправки</option></select></div><button type="submit" class="btn btn-outline">Проверить отправку копии</button><p id="copy-status" role="status"></p></form></section>`:''}<div class="btn-row">${['pending','issuance'].includes(order.status)?btn('resolve-order',order.status==='pending'?'Проверить статус того же заказа':'Проверить готовность образцов','','btn btn-primary'):btn('new-order',order.status==='declined'?'Вернуться к выбору':'Собрать другой демо-заказ','','btn btn-outline')}</div><p class="helper">${storageAvailable?'Заказ сохранён в этом браузере. Для другого устройства скачайте файл.':'Хранилище недоступно. Заказ сохранён только в памяти этой вкладки; обновление или закрытие может его потерять. Скачайте образцы сразу после выдачи.'}</p></section>`;}
function renderTickets(){if(order)return `<section class="hero"><div class="hero-copy"><p class="eyebrow">Ваш семейный день</p><h1>Заказ <span>сохранён</span></h1></div></section>${receipt()}`;return `<section class="hero"><div class="hero-copy"><p class="eyebrow">Меньше считать. Больше кататься.</p><h1>Билеты под<br><span>ваш день в парке</span></h1><p>Выберите готовый семейный вариант или конкретные продукты. Все цены и условия ниже учебные.</p><div class="btn-row"><a class="btn btn-outline" href="attractions.html#plan">Изменить семейный план</a><a class="btn btn-text" href="#direct">Выбрать самому</a></div></div><figure class="hero-photo"><img src="assets/autodrom.webp" width="700" height="440" alt="Автодром Victory Park"><figcaption>Фото настоящего парка. Продукты ниже учебные.</figcaption></figure></section>${modeSwitch()}${state.party.length?`<div class="notice">${esc(state.party.map(p=>p.label+(p.age!==null?' ('+p.age+' лет)':'')).join(' · '))}. <a href="attractions.html#family">Изменить</a></div>`:''}${undoCart?`<div class="notice undo-banner" role="status">Товары удалены. ${btn('undo-remove','Вернуть удалённое','','btn btn-text')}</div>`:''}<div class="buy-layout"><div>${state.wishes.length?recommendations():`<section class="empty"><h2>Можно сразу выбрать билеты</h2><p>Семейная анкета не обязательна. Если хотите сравнить варианты под программу, <a href="attractions.html#family">начните с подбора</a>.</p></section>`}${directProducts()}</div>${cart()}</div>`;}

function render(){const active=document.activeElement?.id, activeData=document.activeElement?.dataset, activeRegion=document.activeElement?.closest('#cart')?'cart':'';document.body.dataset.mode=state.mode;$('#app').innerHTML=(warning?notice(warning,'error'):'')+(state._issues?.length?notice('Сохранённый выбор повреждён. Пересоздайте учебный пример или начните заново.','error')+btn('reset-state','Начать заново','','btn btn-outline'):'')+(document.body.dataset.page==='picker'?renderPicker():renderTickets());$('#cart-count').textContent=state.cart.lines.length?' ('+state.cart.lines.reduce((s,l)=>s+l.quantity,0)+')':'';$('#mobile').innerHTML=order?'':`<div class="mobile-bar"><div><strong>${document.body.dataset.page==='picker'?state.selections[state.mode].length+' в плане':money(VP.cartTotal(state.cart))}</strong><small>${document.body.dataset.page==='picker'?'Выберите, кто катается':'Учебная сумма заказа'}</small></div><a class="btn btn-primary" href="${document.body.dataset.page==='picker'?'#plan':'#cart'}">${document.body.dataset.page==='picker'?'Наш план':'К заказу'}</a></div>`;if(active&&document.getElementById(active))document.getElementById(active).focus({preventScroll:true});if(!active&&activeData?.action){const next=Array.from(document.querySelectorAll('[data-action]')).find(el=>(!activeRegion||el.closest('#cart'))&&['action','person','ride','line','variant','target','value','product'].every(k=>el.dataset[k]===activeData[k]));next?.focus({preventScroll:true});}if(returnFocusData&&!$('#dialog').open){const data=returnFocusData;returnFocusData=null;const target=Array.from(document.querySelectorAll('[data-action]')).find(el=>el.getClientRects().length&&(!data.region||el.closest('#cart'))&&['action','person','ride','line','variant','target','value','product'].every(k=>el.dataset[k]===data[k]));if(target)target.focus({preventScroll:true});else{const h=$('#plan h2')||$('#main');h.tabIndex=-1;h.focus({preventScroll:true});}}$('#family')?.addEventListener('toggle',e=>{if(e.target.isConnected)familyOpen=e.target.open;});}
let dialogReturn=null, returnFocusData=null;
function openDialog(title,body){dialogReturn=document.activeElement;returnFocusData={...dialogReturn?.dataset,region:dialogReturn?.closest('#cart')?'cart':''};$('#dialog').innerHTML=`<button type="button" class="dialog-close" data-action="close-dialog" aria-label="Закрыть">×</button><h2 id="dialog-title">${esc(title)}</h2>${body}`;$('#dialog').showModal();document.body.classList.add('dialog-open');}
$('#dialog').addEventListener('close',()=>{document.body.classList.remove('dialog-open');if(dialogReturn?.isConnected)dialogReturn.focus();});
function showHeight(id){const p=person(id), selected=state.wishes.filter(w=>w.personId===id).map(w=>ride(w.rideId)).filter(Boolean),opts=VP.heightOptions?VP.heightOptions(p,selected):[];openDialog('Рост: '+p.label,`<p>Уточняем только то, что влияет на выбранные катания. Возраст не позволяет узнать рост.</p>${opts.length?`<div class="chips">${opts.map((o,i)=>btn('height-band',esc(o.label),`data-person="${id}" data-band="${i}"`,'chip')).join('')}</div>`:''}<form id="height-form" data-person="${id}"><div class="field"><label for="height-exact">Рост в сантиметрах, если знаете точно</label><input id="height-exact" inputmode="decimal" type="text" value="${p.height??''}" placeholder="Например, 118,5" autocomplete="off"><span class="helper">Не округляйте пограничный рост. Это не замена измерению у аттракциона.</span><span id="height-error" class="field-error" role="alert"></span></div><div class="btn-row"><button class="btn btn-primary" type="submit">Сохранить рост</button>${btn('height-unknown','Пока не знаю',`data-person="${id}"`,'btn btn-outline')}</div></form>`);}
function details(id){const r=ride(id);openDialog(r.name,`${r.photo?`<img src="${esc(r.photo)}" alt="${esc(r.name)}" width="600" height="360">`:'<span class="badge" data-tone="demo">Вымышленный аттракцион</span>'}<p>${r.rules?`Учебные условия: рост от ${r.rules.min} до ${r.rules.max} см включительно. Самостоятельно от ${r.rules.soloMin} см.${r.rules.soloMin>r.rules.min?' Ниже этого порога нужен взрослый сопровождающий. Его рост тоже нужно проверить.':''}`:'Правила допуска не подтверждены. Ни возраст, ни введённый рост не дадут здесь разрешение кататься.'}</p><p>${r.ageRange?'Редакционная учебная подсказка: может заинтересовать в '+r.ageRange[0]+'-'+r.ageRange[1]+' лет. Это не ограничение и не допуск.':'Подтверждённой рекомендации по возрасту нет.'}</p><p>Работа в день визита не подтверждена.</p><div class="btn-row">${btn('toggle-ride',state.selections[state.mode].includes(id)?'Убрать из плана':'Добавить в наш план',`data-ride="${id}"`,'btn btn-primary')}${btn('close-dialog','Закрыть','','btn btn-outline')}</div>`);}

function chooseOffer(id){if(!canEditCommerce())return;undoCart=null;const v=VP.recommend(state).variants.find(v=>v.id===id);if(!v)return;const apply=()=>{state._issues=(state._issues||[]).filter(x=>x!=='cart');state.cart={lines:clone(v.lines),sourcePlanKey:VP.planKey(state),scope:'plan'};activeProduct=v.lines.some(l=>l.productId==='unlimited')?'unlimited':v.lines.some(l=>l.productId==='package5')?'package':'single';update('Выбранный вариант добавлен в заказ.');$('#cart')?.scrollIntoView({block:'start'});};if(state.cart.lines.length){openDialog('Заменить состав заказа?',`<p>Будет выбран вариант «${esc(v.title)}» за ${money(v.total)}. Текущие товары на ${money(VP.cartTotal(state.cart))} будут заменены.</p><ul>${v.lines.map(l=>'<li>'+lineSummary(l)+'</li>').join('')}</ul><div class="btn-row">${btn('confirm-offer','Заменить заказ',`data-variant="${id}"`,'btn btn-primary')}${btn('close-dialog','Оставить как есть','','btn btn-outline')}</div>`);}else apply();}
function saveOrder(){try{localStorage.setItem(ORDER,JSON.stringify(order));}catch{storageAvailable=false;warning='Статус демо-заказа не сохранён. Не закрывайте вкладку. После обновления восстановление не гарантируется.';}}

function canEditCommerce(){if(busy||order){announce('Сначала завершите текущий демо-заказ.');return false;}return true;}
function commitCart(next,message,before=null){state=next;state._issues=(state._issues||[]).filter(x=>x!=='cart');state=VP.sanitizeState(state);state.cart.sourcePlanKey=null;if(!state.wishes.length)state.cart.scope='direct';undoCart=before?{lines:before,after:JSON.stringify(state.cart.lines)}:null;update(message);}
function currentQuantity(target){if(target==='passes')return state.cart.lines.filter(l=>l.productId==='unlimited').length;if(target==='package5')return state.cart.lines.filter(l=>l.productId==='package5').reduce((a,l)=>a+l.quantity,0);if(target.startsWith('ticket:'))return state.cart.lines.find(l=>l.productId==='ticket'&&!l.personId&&l.rideId===target.slice(7))?.quantity||0;return state.cart.lines.find(l=>l.id===target.slice(5))?.quantity||0;}
function changeQuantity(target,n,keepIds){if(!canEditCommerce())return;if(!Number.isInteger(n)||n<0||n>VP.MAX_QUANTITY){announce('Введите целое число от 1 до 20. Заказ не изменён.');return;}const old=clone(state.cart.lines),previous=currentQuantity(target);if(n===previous)return;
 if(target==='passes'){const result=VP.resizePasses(state,n,keepIds);if(result.error){$('#recipient-error').textContent=result.error;return;}if(result.needsSelection){openDialog('Кому оставить безлимит?',`<p>В заказе останется ${n} личных прав вместо ${previous}. Выберите получателей. Пока выбор не подтверждён, заказ не меняется.</p><form id="keep-recipients-form" data-count="${n}">${result.lines.map((l,i)=>`<label class="participant-choice"><input type="checkbox" name="keep-recipient" value="${l.id}"><span>${esc(l.personId?personName(l.personId):'Неназначенный получатель '+(i+1))}</span></label>`).join('')}<p id="recipient-error" class="field-error" role="alert"></p><button type="submit" class="btn btn-primary">Оставить выбранных</button></form>`);return;}commitCart(result.state,n>previous?'Количество изменено. Новые личные права пока не назначены. Выберите получателей ниже.':'Количество изменено. Покрытие программы пересчитано.',n<previous?old:null);return;}
 let next=clone(state),l;if(target.startsWith('line:'))l=next.cart.lines.find(l=>l.id===target.slice(5));else if(target==='package5')l=next.cart.lines.find(l=>l.productId==='package5');else if(target.startsWith('ticket:'))l=next.cart.lines.find(l=>l.productId==='ticket'&&!l.personId&&l.rideId===target.slice(7));
 if(l){if(n===0)next.cart.lines=next.cart.lines.filter(x=>x.id!==l.id);else l.quantity=n;}else if(n){const productId=target==='package5'?'package5':'ticket',rid=productId==='ticket'?target.slice(7):null;if(productId==='ticket'&&!VP.demoRides.some(r=>r.id===rid))return;next.cart.lines.push({id:safeId(),productId,rideId:rid,personId:null,quantity:n,unitPrice:productId==='ticket'?ride(rid).price:VP.products.package5.price,visitDate:'',mode:'demo'});}
 next.mode='demo';commitCart(next,n?'Количество изменено. Покрытие программы пересчитано.':'Товары удалены. Можно отменить.',n<previous?old:null);
}
function openQuantity(target){if(!canEditCommerce())return;quantityTarget=target;openDialog('Другое количество',`<form id="quantity-form" novalidate><div class="field"><label for="custom-quantity">Количество от 1 до ${VP.MAX_QUANTITY}</label><input id="custom-quantity" type="text" inputmode="numeric" autocomplete="off" value="${currentQuantity(target)||''}" aria-describedby="quantity-error"><span id="quantity-error" class="field-error" role="alert"></span></div><button type="submit" class="btn btn-primary">Применить количество</button></form>`);$('#custom-quantity').focus();}
function setDate(value){if(!canEditCommerce())return;state.visitDate=value;state.cart.lines.filter(l=>l.productId==='unlimited').forEach(l=>l.visitDate=value);undoCart=null;update('Дата изменена. Сверьте покрытие и дату заказа.');}
function focusProduct(type,fromQuery=false){activeProduct=['single','package','unlimited'].includes(type)?type:'single';render();const tab=document.getElementById('tab-'+activeProduct);if(fromQuery){document.getElementById('direct')?.scrollIntoView({block:'start'});}tab?.focus({preventScroll:true});}

function download(name,html){const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function saveTickets(){if(!order||order.status!=='success')return;const css='body{font:16px/1.5 Arial,sans-serif;color:#2f2e7d;max-width:850px;margin:24px auto;padding:20px}h1{font-size:30px}h3{font-size:22px}.demo-ticket{border:2px solid #2f2e7d;border-radius:16px;padding:22px;margin:18px 0;break-inside:avoid}.ticket-top{display:flex;justify-content:space-between;gap:15px;font-size:12px}.ticket-code{font:13px monospace;overflow-wrap:anywhere}.ticket-demo{font-weight:bold}details{margin:14px 0}';download(order.id+'-demo-tickets.html',`<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Демо-билеты ${esc(order.id)}</title><style>${css}</style></head><body><h1>Ваши демо-билеты</h1><p>${esc(order.id)} · ${money(order.total)}</p><p>Все документы являются образцами. Деньги не списывались. Для прохода не действуют.</p>${ticketCards(order).replaceAll('<details>','<details open>')}<p>Создано: ${esc(order.createdAt)}. Контакт для получения образцов не требовался. Реальный порядок прохода и активации парк ещё не подтвердил.</p></body></html>`);announce('Подготовлен один файл со всеми образцами.');}
function syncOrder(){try{const saved=restoreOrder(localStorage.getItem(ORDER));if(saved){order=saved;return true;}}catch{storageAvailable=false;}return false;}
async function pay(){if(busy||order)return;if(syncOrder()){render();return;}const a=VP.assessCart(state);if(!a.canCheckout){$('#checkout-errors').innerHTML=messages(a.errors,'error')+notice(a.stale?'План изменился. Перепроверьте текущий заказ.':a.uncovered.length?'Часть программы не покрыта. Измените товары или выберите самостоятельную покупку.':'Проверьте условия, получателей и дату.','error');$('#checkout-errors').scrollIntoView({block:'center'});return;}const chosen=$('#scenario').value;busy=true;
 const run=async()=>{if(syncOrder()){busy=false;render();return;}order=VP.snapshotOrder(state,'DEMO-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2,10)));if(!order){busy=false;render();return;}saveOrder();render();await new Promise(resolve=>setTimeout(resolve,350));order.status=chosen;saveOrder();busy=false;render();window.scrollTo({top:0});$('#result-heading')?.focus({preventScroll:true});announce(chosen==='success'?'Все образцы готовы. Контакт не требуется.':chosen==='pending'?'Результат неизвестен. Проверяйте тот же заказ.':chosen==='issuance'?'Оплачено, ожидается выдача.':'Оплата отклонена.');};
 try{if(navigator.locks?.request)await navigator.locks.request('vp.integrated.payment.v1',run);else {busy=false;warning='В этом браузере недоступна защита демонстрационного заказа между вкладками. Откройте прототип в современном браузере с поддержкой Web Locks.';render();}}catch{busy=false;if(order){order.status='pending';saveOrder();}warning='Статус демо-заказа пока неизвестен. Не создавайте новый заказ до проверки.';render();}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.person,rid=b.dataset.ride;
if(act==='reset-state'){state=VP.emptyState();state.mode='demo';update('План и корзина очищены.');return;}
if(act==='scope-direct'){openDialog('Купить выбранные товары?',`<p>Корзина на ${money(VP.cartTotal(state.cart))} останется прежней. Семейная программа сохранится, но её полноту мы проверять не будем. Вы сами выбираете, достаточно ли этих товаров.</p><p>Условия продуктов, дата и получатели личных безлимитов продолжают действовать. Известное несоответствие назначенного билета не обходится.</p><div class="btn-row">${btn('confirm-direct','Купить самостоятельно','','btn btn-primary')}${btn('close-dialog','Вернуться к семейному расчёту','','btn btn-outline')}</div>`);return;}
if(act==='confirm-direct'){state.cart.scope='direct';state.cart.sourcePlanKey=null;$('#dialog').close();update('Прямая покупка включена. Семейный план сохранён.');return;}
if(act==='scope-plan'){state.cart.scope='plan';update('Проверка семейной программы включена.');return;}
if(act==='close-dialog'){$('#dialog').close();return;}
if(act==='mode'){state.mode=b.dataset.mode;focusPerson='';update();return;}
if(act==='sample'){if(state.party.length||state.cart.lines.length){openDialog('Загрузить учебную семью?',`<p>Пример заменит текущую семью, программу и корзину. Двое взрослых, дети 6 и 11 лет. Пять спокойных катаний младшему, шесть «Виражей» и два совместных катания старшему.</p><div class="btn-row">${btn('confirm-sample','Загрузить пример','','btn btn-primary')}${btn('close-dialog','Сохранить свой выбор','','btn btn-outline')}</div>`);}else{state=VP.sampleState();familyOpen=false;update('Загружен учебный пример.',false);}return;}
if(act==='confirm-sample'){state=VP.sampleState();familyOpen=false;$('#dialog').close();update('Загружен учебный пример.',false);return;}
if(act==='add-adult'||act==='add-child'){addPerson(act==='add-adult'?'adult':'child');update();$('#family').open=true;return;}
if(act==='remove-person'){state.party=state.party.filter(p=>p.id!==id);state.wishes=state.wishes.filter(w=>w.personId!==id);if(focusPerson===id)focusPerson='';update('Участник и его желания убраны. Товары заказа сохранены.');return;}
if(act==='collapse-family'){$('#family').open=false;familyOpen=false;return;}
if(act==='focus-person'){focusPerson=id;update();return;}
if(act==='height'){showHeight(id);return;}
if(act==='height-unknown'){const p=person(id);p.height=null;p.heightRange=null;$('#dialog').close();update('Рост оставлен неизвестным.');return;}
if(act==='height-band'){const p=person(id),opts=VP.heightOptions(p,state.wishes.filter(w=>w.personId===id).map(w=>ride(w.rideId)).filter(Boolean)),o=opts[Number(b.dataset.band)];p.height=null;p.heightRange=o.range||[o.min,o.maxExclusive];$('#dialog').close();update('Диапазон роста сохранён.');return;}
if(act==='ride-details'){details(rid);return;}
if(act==='toggle-ride'){let ids=state.selections[state.mode];if(ids.includes(rid)){state.selections[state.mode]=ids.filter(x=>x!==rid);state.wishes=state.wishes.filter(w=>w.rideId!==rid);}else ids.push(rid);if($('#dialog').open)$('#dialog').close();update('План обновлён. Укажите, кто хочет кататься.');return;}
if(act==='one-each'){state.wishes.filter(w=>state.selections[state.mode].includes(w.rideId)&&w.count===null).forEach(w=>w.count=1);update('Неизвестные повторы приняты за одно катание по вашему выбору.');return;}
if(act==='choose-offer'){chooseOffer(b.dataset.variant);return;}
if(act==='confirm-offer'){if(!canEditCommerce())return;const v=VP.recommend(state).variants.find(v=>v.id===b.dataset.variant);if(v){state._issues=(state._issues||[]).filter(x=>x!=='cart');state.cart={lines:clone(v.lines),sourcePlanKey:VP.planKey(state),scope:'plan'};activeProduct=v.lines.some(l=>l.productId==='unlimited')?'unlimited':v.lines.some(l=>l.productId==='package5')?'package':'single';}$('#dialog').close();update('Заказ заменён выбранным вариантом.');return;}
if(act==='quantity'){changeQuantity(b.dataset.target,Number(b.dataset.value));return;}
if(act==='quantity-other'){openQuantity(b.dataset.target);return;}
if(act==='quantity-remove'){changeQuantity(b.dataset.target,0);return;}
if(act==='undo-remove'){if(!canEditCommerce()||!undoCart)return;if(JSON.stringify(state.cart.lines)!==undoCart.after){undoCart=null;update('Заказ уже изменён. Отмена старого удаления недоступна.');return;}state.cart.lines=clone(undoCart.lines);state.cart.sourcePlanKey=null;undoCart=null;update('Удалённые товары и получатели восстановлены.');return;}
if(act==='date-today'||act==='date-tomorrow'){setDate(VP.todayInYerevan(null,act==='date-tomorrow'?1:0));return;}
if(act==='product-focus'){focusProduct(b.dataset.product);return;}
if(act==='save-tickets'){saveTickets();return;}
if(act==='toggle-copy'){const f=$('#copy-form');f.hidden=!f.hidden;b.setAttribute('aria-expanded',String(!f.hidden));if(!f.hidden)$('#copy-email').focus();return;}
if(act==='accept-current'){state.cart.sourcePlanKey=VP.planKey(state);update('Товары сохранены, покрытие проверяется по текущему плану.');return;}
if(act==='resolve-order'){if(busy||!order)return;order.status=order.status==='pending'?'issuance':'success';saveOrder();render();return;}
if(act==='new-order'){if(busy||!order||['pending','issuance'].includes(order.status))return;const clear=order.status==='success';order=null;try{localStorage.removeItem(ORDER);}catch{warning='Не удалось очистить сохранённый демо-статус.';}if(clear)state.cart={lines:[],sourcePlanKey:null,scope:'direct'};update();return;}
});
document.addEventListener('change',e=>{const t=e.target,k=t.dataset.change;if(!k)return;if(k==='date'){setDate(t.value);return;}if(k==='recipient'){if(!canEditCommerce())return;const result=VP.assignPass(state,t.dataset.line,t.value);if(result.error){t.value=state.cart.lines.find(l=>l.id===t.dataset.line)?.personId||'';announce(result.error);openDialog('Получатель уже выбран',notice(result.error,'error'));return;}commitCart(result.state,'Получатель изменён. Покрытие пересчитано.');return;}const p=person(t.dataset.person),rid=t.dataset.ride;if(k==='age')p.age=t.value===''?null:Number(t.value);if(k==='preference')p.preference=t.value;if(k==='companion')p.canAccompany=t.checked;if(k==='wish'){if(t.checked)state.wishes.push({personId:p.id,rideId:rid,count:null});else state.wishes=state.wishes.filter(w=>!(w.personId===p.id&&w.rideId===rid));}if(k==='count')state.wishes.find(w=>w.personId===p.id&&w.rideId===rid).count=t.value===''?null:Number(t.value);if(k==='date'){state.visitDate=t.value;state.cart.lines.filter(l=>l.productId==='unlimited').forEach(l=>l.visitDate=t.value);}update('Данные обновлены.');});
document.addEventListener('submit',e=>{if(e.target.id==='height-form'){e.preventDefault();const raw=$('#height-exact').value.trim().replace(',','.');if(!/^\d{2,3}(\.\d{1,2})?$/.test(raw)||Number(raw)<40||Number(raw)>250){$('#height-error').textContent='Введите рост от 40 до 250 см, можно с двумя знаками после запятой.';$('#height-exact').setAttribute('aria-invalid','true');return;}const p=person(e.target.dataset.person);p.height=Number(raw);p.heightRange=null;$('#dialog').close();update('Рост сохранён без округления.');}
if(e.target.id==='checkout-form'){e.preventDefault();pay();}
if(e.target.id==='quantity-form'){e.preventDefault();const raw=$('#custom-quantity').value.trim(),n=Number(raw);if(!/^\d+$/.test(raw)||!Number.isInteger(n)||n<1||n>VP.MAX_QUANTITY){$('#quantity-error').textContent='Введите целое число от 1 до 20. Заказ не изменён.';$('#custom-quantity').setAttribute('aria-invalid','true');$('#custom-quantity').focus();return;}const target=quantityTarget;$('#dialog').close();changeQuantity(target,n);}
if(e.target.id==='keep-recipients-form'){e.preventDefault();const n=Number(e.target.dataset.count),ids=[...e.target.querySelectorAll('input:checked')].map(x=>x.value),result=VP.resizePasses(state,n,ids);if(result.error){$('#recipient-error').textContent=result.error;return;}$('#dialog').close();changeQuantity('passes',n,ids);}
if(e.target.id==='copy-form'){e.preventDefault();const email=$('#copy-email');if(!email.value.trim()||!email.validity.valid){email.setAttribute('aria-invalid','true');$('#copy-status').textContent='Проверьте адрес. Все билеты остаются доступными.';email.focus();}else{email.removeAttribute('aria-invalid');$('#copy-status').textContent=$('#copy-outcome').value==='failed'?'Сбой копии в демо-сценарии. Все билеты доступны: сохраните файл.':'Имитация завершена. Настоящее письмо не отправлено. Адрес не сохранён.';}}

});
document.addEventListener('keydown',e=>{if(!e.target.matches('[role="tab"][data-product]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=['single','package','unlimited'],i=ids.indexOf(e.target.dataset.product),next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;focusProduct(ids[next]);});
window.addEventListener('storage',e=>{if(e.key===ORDER){try{order=restoreOrder(e.newValue);render();announce('Статус заказа обновлён в другой вкладке.');}catch{warning='Не удалось прочитать статус заказа из другой вкладки.';render();}return;}if(e.key===KEY){try{state=VP.sanitizeState(JSON.parse(e.newValue));render();announce('Выбор обновлён в другой вкладке.');}catch{warning='Изменение из другой вкладки не прочитано.';render();}}});
const requestedType=new URLSearchParams(location.search).get('type');if(['single','package','unlimited'].includes(requestedType))activeProduct=requestedType;else if(state.cart.lines.some(l=>l.productId==='unlimited'))activeProduct='unlimited';else if(state.cart.lines.some(l=>l.productId==='package5'))activeProduct='package';
render();
if(document.body.dataset.page==='tickets'&&requestedType&&!order)requestAnimationFrame(()=>focusProduct(requestedType,true));
})();
